(() => {
  const getText = (sel) => {
    const el = document.querySelector(sel);
    return el ? el.textContent.trim() : '';
  };

  // 多选择器降级：CSDN 不同版本/皮肤可能用不同的容器
  let content = getText('#content_views');
  if (!content || content.length < 100) {
    content = getText('article.baidu_pl');
  }
  if (!content || content.length < 100) {
    content = getText('#article_content');
  }
  if (!content || content.length < 100) {
    content = getText('.article-detail');
  }
  if (!content || content.length < 100) {
    // 最后尝试取 body 内文章区域
    const main = document.querySelector('main') || document.querySelector('.main_content');
    content = main ? main.textContent.trim() : '';
  }

  // 截取前 5000 字（足够 LLM 理解文章主旨，也避免 prompt 过长）
  content = content.substring(0, 5000);

  // 标题
  const title = getText('#articleContentId') || getText('h1.title-article') || document.title || '';

  return { title: title, content: content };
})()
